import { ViewWithdrawDetails } from '@/Components/Feature/Backend/ViewWithdrawDetails';
import StatusBadge from '@/Components/UI/StatusBadge';
import { useTranslations } from '@/Hooks/useTranslations';
import type { CrudConfig, CrudPageProps } from '@/Types/crud';

export function useWithdrawConfig(props: CrudPageProps): CrudConfig {
    const { t } = useTranslations();

    const modelProperty = props?.modelProperty;
    const routePrefix = modelProperty?.routePrefix;
    const advanceFilterOptions = props?.advanceFilterOptions || [];

    const baseBreadcrumbs = [
        { label: t('Dashboard'), href: route('backend.dashboard') },
        { label: t('Withdraw'), href: route(`${routePrefix}.index`) },
    ];

    return {
        resource: 'withdraw',
        resourcePlural: 'withdraws',

        title: t('Withdraw'),
        description: t('Manage withdraw requests'),


        viewDisplayMode: 'modal',
        viewDialogConfig: {
            size: 'xl',
            title: t('View withdraw'),
            description: t('View withdraw informatio and action'),
            viewComponent: ViewWithdrawDetails,
        },

        routes: {
            show: `${routePrefix}.show`,
            index: `${routePrefix}.index`,
            destroy: `${routePrefix}.delete`,
        },

        breadcrumbs: {
            index: [
                { label: t('Dashboard'), href: route('backend.dashboard') },
                { label: t('Withdraw'), href: null, active: true },
            ],

        },

        table: {
            serializable: true,
            searchable: true,
            sortable: false,
            selectable: false,

            columns: [
                {
                    key: 'user',
                    label: t('User'),
                    render: (row: any) => (
                        <div>
                            <p className="font-medium">{row?.user?.name}</p>
                            <p className="text-xs text-gray-500">{row?.user?.email}</p>
                        </div>
                    ),
                },


                {
                    key: 'withdrawal_address',
                    label: t('Withdrawal Address'),
                    render: (row: any) => (
                        <div className="text-sm text-gray-900 dark:text-gray-100">{row.withdrawal_address}</div>
                    )
                },

                {
                    key: 'Withdraw Info',
                    label: t('Withdraw Info'),
                    render: (row: any) => (
                        <div className="flex flex-col gap-1 text-sm">

                            <div className="flex items-center justify-between gap-4">
                                <span className="text-gray-400">{t('Amount')}</span>
                                <div className="flex items-center gap-1.5">
                                    <span>{row.amount}</span>
                                </div>
                            </div>

                            <div className="flex items-center justify-between gap-4">
                                <span className="text-gray-400">{t('Fee')}</span>
                                <span>{row.fee_pct ? Number(row.fee_pct)?.toFixed(2) : 0}%</span>
                            </div>

                            <div className="flex items-center justify-between gap-4">
                                <span className="text-gray-400">{t('Fee Charged')}</span>
                                <div className="flex items-center gap-1.5">
                                    <span>{row.fee_charged}</span>
                                </div>
                            </div>

                            <div className="flex items-center justify-between gap-4">
                                <span className="text-gray-400">{t('Final Amount')}</span>
                                <div className="flex items-center gap-1.5 font-medium">
                                    <span>{row.final_amount}</span>
                                </div>
                            </div>

                        </div>
                    )

                },
                {
                    key: 'status',
                    label: t('Status'),
                    render: (row: any) => <StatusBadge status={row.status} />,
                },

                {
                    key: 'created_at',
                    label: t('Created At'),
                    sortable: false,
                    renderType: 'date',
                },
            ],
        },

        filters: {
            searchFields: ['username', 'email', 'phone', 'name', 'withdrawal_address'],
            filterFields: advanceFilterOptions,
        },

        permissions: {
            actions: {
                view: 'withdraw.view',
                edit: 'withdraw.edit',
                delete: 'withdraw.delete',
            },
        }
    };
}